import torch, torch.nn.functional as F, time
torch.manual_seed(0)
dev='cuda'
def ref(x,w1,b1,gw,gb,w2,b2,eps, mm=None):
    h=F.linear(x,w1,b1) if mm is None else mm(x,w1)+b1
    h=F.gelu(h)
    G=torch.linalg.vector_norm(h,ord=2,dim=(1,2),keepdim=True)
    nf=G/(G.mean(dim=-1,keepdim=True)+eps)
    h=gw*(h*nf)+gb+h
    return F.linear(h,w2,b2) if mm is None else mm(h,w2)+b2
def tf32r(t):  # round-to-nearest tf32 emulation
    i=t.view(torch.int32); i=(i+0x1000)&~0x1fff; return i.view(torch.float32)
def mm_tf32(a,w): return (tf32r(a.contiguous())@tf32r(w.contiguous()).t())
def mm_3tf32(a,w):
    ah=tf32r(a.contiguous()); al=tf32r(a-ah); wh=tf32r(w.contiguous()); wl=tf32r(w-wh)
    return ah@wh.t()+(ah@wl.t()+al@wh.t())
def mm_bf16x3(a,w):
    ah=a.bfloat16().float(); al=(a-ah).bfloat16().float(); wh=w.bfloat16().float(); wl=(w-wh).bfloat16().float()
    return ah@wh.t()+(ah@wl.t()+al@wh.t())
def mm_fp16(a,w): return a.half().float()@w.half().float().t()
for (B,H,W,atol) in [(16,14,14,0.0028),(64,14,14,0.0034),(16,56,56,0.003)]:
    x=torch.randn(B,H,W,128,device=dev); w1=torch.randn(512,128,device=dev); b1=torch.randn(512,device=dev)
    gw=torch.randn(1,1,1,512,device=dev); gb=torch.randn(1,1,1,512,device=dev); w2=torch.randn(128,512,device=dev); b2=torch.randn(128,device=dev)
    r=ref(x,w1,b1,gw,gb,w2,b2,1e-6)
    r64=ref(*(t.double() for t in (x,w1,b1,gw,gb,w2,b2)),1e-6)
    print(B,H,W,'ref std %.1f max %.1f'%(r.std(),r.abs().max()))
    def rep(name,o):
        d=(o.double()-r.double()).abs(); tol=atol+1e-5*r.double().abs()
        print('  %-8s maxerr %.2e  fail %.4f%%'%(name,d.max(),100*(d>tol).float().mean()))
    rep('fp64',r64)
    torch.backends.cuda.matmul.allow_tf32=False
    for nm,f in [('tf32',mm_tf32),('3tf32',mm_3tf32),('bf16x3',mm_bf16x3)]:
        rep(nm,ref(x,w1,b1,gw,gb,w2,b2,1e-6,mm=lambda a,w,f=f: f(a.reshape(-1,a.shape[-1]),w).reshape(*a.shape[:-1],w.shape[0])))
# GEMM timing fp32 vs tf32 at largest size
M=64*56*56
a=torch.randn(M,128,device=dev); w=torch.randn(512,128,device=dev)
for tf in [False,True]:
    torch.backends.cuda.matmul.allow_tf32=tf
    for _ in range(3): c=a@w.t()
    torch.cuda.synchronize(); t=time.perf_counter()
    for _ in range(20): c=a@w.t()
    torch.cuda.synchronize(); print('gemm1 M=%d tf32=%s %.1f us'%(M,tf,(time.perf_counter()-t)/20*1e6))
print(torch.cuda.get_device_name(), torch.cuda.get_device_properties(0).multi_processor_count)

